frames.bend.source:
import Base

# A lease is affine even though its serial is observable Data. All resumption
# sites transfer this live owner, never copy or replace it with its serial.
type Owner is Type:
  Lease{serial: Nat}

type Owned is Type:
  Owned{owner: Owner, value: Nat, trace: Nat}

type Site is Data:
  BumpSite{}
  CaptureSite{}
  FinishSite{}

# Three source continuation sites, all first-order environments.
type BumpFrame is Data:
  BumpFrame{digit: Nat}

type CaptureFrame is Type:
  CaptureOwner{owner: Owner, digit: Nat}

type FinishFrame is Data:
  FinishFrame{digit: Nat}

def Frame(site: Site) -> Type:
  match site:
    case BumpSite{}: BumpFrame
    case CaptureSite{}: CaptureFrame
    case FinishSite{}: FinishFrame

def Input(site: Site) -> Type:
  match site:
    case BumpSite{}: Nat
    case CaptureSite{}: Nat
    case FinishSite{}: Owned

def Output(site: Site) -> Type:
  match site:
    case BumpSite{}: Nat
    case CaptureSite{}: Owned
    case FinishSite{}: Owned

def append(trace: Nat, digit: Nat) -> Nat:
  Nat.add(Nat.mul(trace, 10n), digit)

# Expose the concrete Data binder before contracting the Nat. The open
# Input(site) family conservatively has kind Type, even in the refined arm.
def capture(owner: Owner, +number: Nat, digit: Nat) -> Owned:
  Owned{owner, number, append(number, digit)}

# Matching the closed site refines all three families together; no cast or
# equality witness is supplied, and the owner is moved out of its frame once.
def apply(site: Site, frame: Frame(site), input: Input(site)) -> Output(site):
  match site:
    case BumpSite{}:
      match frame:
        case BumpFrame{digit}: append(input, digit)
    case CaptureSite{}:
      match frame:
        case CaptureOwner{owner, digit}: capture(owner, input, digit)
    case FinishSite{}:
      match frame:
        case FinishFrame{digit}:
          match input:
            case Owned{owner, value, trace}: Owned{owner, value, append(trace, digit)}

# Requests and their genuine dependent result family follow production's
# request/result pattern. The second request itself owns a live lease.
type Request is Type:
  NumberRequest{seed: Nat}
  LeaseRequest{owner: Owner, seed: Nat}

def RequestResult(request: Request) -> Type:
  match request:
    case NumberRequest{seed}: Nat
    case LeaseRequest{owner, seed}: Owned

def request_step(request: Request) -> RequestResult(request):
  match request:
    case NumberRequest{seed}: seed
    case LeaseRequest{owner, seed}:
      +number = seed
      Owned{owner, number, number}

# Concrete source-site pending shapes preserve the adjacency invariant
# structurally: Number -> Nat -> Owned -> Owned. No boxed existential input,
# generic function field, dynamically untyped value or host scheduler exists.
type PendingNat is Type:
  PendingNat{seed: Nat, frame: Frame(BumpSite{})}

type PendingOwned is Type:
  PendingOwned{inner: PendingNat, frame: Frame(CaptureSite{})}

type PendingFinish is Type:
  PendingFinish{inner: PendingOwned, frame: Frame(FinishSite{})}

def run_nat(pending: PendingNat) -> Nat:
  match pending:
    case PendingNat{seed, frame}:
      apply(BumpSite{}, frame, request_step(NumberRequest{seed}))

def run_owned(pending: PendingOwned) -> Owned:
  match pending:
    case PendingOwned{inner, frame}:
      apply(CaptureSite{}, frame, run_nat(inner))

def run_finish(pending: PendingFinish) -> Owned:
  match pending:
    case PendingFinish{inner, frame}:
      apply(FinishSite{}, frame, run_owned(inner))

type Summary is Data:
  Summary{serial: Nat, value: Nat, trace: Nat}

# The only observer consumes the resulting live owner exactly once.
def close(result: Owned) -> Summary:
  match result:
    case Owned{owner, value, trace}:
      match owner:
        case Lease{serial}: Summary{serial, value, trace}

def exercise(serial: Nat, seed: Nat, first: Nat, second: Nat, third: Nat) -> Summary:
  close(run_finish(PendingFinish{
    PendingOwned{
      PendingNat{seed, BumpFrame{first}},
      CaptureOwner{Lease{serial}, second}
    },
    FinishFrame{third}
  }))

type Results is Data:
  Results{nested: Summary, other: Summary, request_owned: Summary, direct_nat: Nat}

def main() -> Results:
  Results{
    exercise(7n, 2n, 3n, 4n, 5n),
    exercise(9n, 6n, 1n, 8n, 2n),
    close(request_step(LeaseRequest{Lease{11n}, 8n})),
    apply(BumpSite{}, BumpFrame{9n}, 4n)
  }

generic_stack.bend.source:
import Base
import ./frames.bend as F

def cast(-A: Type, -B: Type, equation: {A == B : Type}, value: A) -> B:
  %equation : _
  value

type Resume<-A: Type, -B: Type> is Type:
  Resume{site: F.Site, frame: F.Frame(site), input: {A == F.Input(site) : Type}, output: {F.Output(site) == B : Type}}

def resume(-A: Type, -B: Type, continuation: Resume<A, B>, value: A) -> B:
  match continuation:
    case Resume{site, frame, input, output}:
      converted = cast(A, F.Input(site), input, value)
      result = F.apply(site, frame, converted)
      cast(F.Output(site), B, output, result)

type Stack<-A: Type, -R: Type> is Type:
  End{equation: {A == R : Type}}
  More{-B: Type, continuation: Resume<A, B>, rest: Stack<B, R>}

def run(-A: Type, -R: Type, stack: Stack<A, R>, value: A) -> R:
  match stack:
    case End{equation}: cast(A, R, equation, value)
    case More{B, continuation, rest}: run(B, R, rest, resume(A, B, continuation, value))

def exercise() -> F.Summary:
  bump = {Resume{F.BumpSite{}, F.BumpFrame{3n}, {==}, {==}} : Resume<Nat, Nat>}
  capture = {Resume{F.CaptureSite{}, F.CaptureOwner{F.Lease{7n}, 4n}, {==}, {==}} : Resume<Nat, F.Owned>}
  finish = {Resume{F.FinishSite{}, F.FinishFrame{5n}, {==}, {==}} : Resume<F.Owned, F.Owned>}
  stack = {More{Nat, bump, More{F.Owned, capture, More{F.Owned, finish, End{{==}}}}} : Stack<Nat, F.Owned>}
  F.close(run(Nat, F.Owned, stack, 2n))

def main() -> F.Summary:
  exercise()

indexed_frames.bend.source:
import Base
import ./frames.bend as F

type Continuation<-A: Type, -R: Type> is Type:
  Bump{digit: Nat, input: {A == Nat : Type}, output: {Nat == R : Type}}
  Capture{owner: F.Owner, digit: Nat, input: {A == Nat : Type}, output: {F.Owned == R : Type}}
  Finish{digit: Nat, input: {A == F.Owned : Type}, output: {F.Owned == R : Type}}
  Keep{-B: Type, value: B, input: {A == Nat : Type}, output: {B == R : Type}}
  Select{site: F.Site, payload: F.Frame(site), input: {A == F.Input(site) : Type}, output: {F.Output(site) == R : Type}}
  Compose{-B: Type, first: Continuation<A, B>, next: Continuation<B, R>}
  Identity{equation: {A == R : Type}}

type Value<-A: Type> is Type:
  Value{value: A}

type Progress<-A: Type> is Type:
  Finished{box: Value<A>}
  Bound{-B: Type, inner: Progress<B>, resume: Continuation<B, A>}

def unbox(-A: Type, box: Value<A>) -> A:
  match box:
    case Value{value}: value

def cast_box(-A: Type, -B: Type, equation: {A == B : Type}, box: Value<A>) -> Value<B>:
  %equation : Value<_>
  box

def cast_progress(-A: Type, -B: Type, equation: {A == B : Type}, progress: Progress<A>) -> Progress<B>:
  %equation : Progress<_>
  progress

def complete_finish(digit: Nat, box: Value<F.Owned>) -> Progress<F.Owned>:
  match box:
    case Value{F.Owned{owner, value, trace}}: Finished{Value{F.Owned{owner, value, F.append(trace, digit)}}}

def resume(-A: Type, -R: Type, continuation: Continuation<A, R>, box: Value<A>) -> Progress<R>:
  match continuation:
    case Bump{digit, input, output}:
      cast_progress(Nat, R, output, Finished{Value{F.append(unbox(Nat, cast_box(A, Nat, input, box)), digit)}})
    case Capture{owner, digit, input, output}:
      cast_progress(F.Owned, R, output, Finished{Value{F.capture(owner, unbox(Nat, cast_box(A, Nat, input, box)), digit)}})
    case Finish{digit, input, output}:
      cast_progress(F.Owned, R, output, complete_finish(digit, cast_box(A, F.Owned, input, box)))
    case Keep{B, value, input, output}:
      cast_progress(B, R, output, Finished{Value{value}})
    case Select{site, payload, input, output}:
      cast_progress(F.Output(site), R, output, Finished{Value{F.apply(site, payload, unbox(F.Input(site), cast_box(A, F.Input(site), input, box)))}})
    case Compose{B, first, next}: Bound{B, resume(A, B, first, box), next}
    case Identity{equation}: Finished{cast_box(A, R, equation, box)}

def chunk(-A: Type, fuel: Nat, progress: Progress<A>) -> Progress<A>:
  match fuel progress:
    case 0n state: state
    case 1n+rest Finished{box}: Finished{box}
    case 1n+rest Bound{B, inner, continuation}:
      match inner:
        case Finished{box}: chunk(A, rest, resume(B, A, continuation, box))
        case Bound{C, nested, next}: chunk(A, rest, Bound{C, nested, Compose{B, next, continuation}})

def finish(progress: Progress<F.Owned>) -> F.Summary:
  match progress:
    case Finished{Value{value}}: F.close(value)
    case _: F.Summary{0n, 0n, 0n}

def composed() -> F.Summary:
  bump = {Bump{3n, {==}, {==}} : Continuation<Nat, Nat>}
  capture = {Capture{F.Lease{7n}, 4n, {==}, {==}} : Continuation<Nat, F.Owned>}
  finish_frame = {Finish{5n, {==}, {==}} : Continuation<F.Owned, F.Owned>}
  all = {Compose{Nat, bump, Compose{F.Owned, capture, finish_frame}} : Continuation<Nat, F.Owned>}
  finish(chunk(F.Owned, 16n, resume(Nat, F.Owned, all, Value{2n})))

def dependent_site() -> F.Summary:
  continuation = {Select{F.CaptureSite{}, F.CaptureOwner{F.Lease{9n}, 8n}, {==}, {==}} : Continuation<Nat, F.Owned>}
  finish(chunk(F.Owned, 8n, resume(Nat, F.Owned, continuation, Value{6n})))

def existential_type() -> F.Summary:
  continuation = {Keep{F.Owned, F.Owned{F.Lease{11n}, 8n, 8n}, {==}, {==}} : Continuation<Nat, F.Owned>}
  identity = {Identity{{==}} : Continuation<F.Owned, F.Owned>}
  all = {Compose{F.Owned, continuation, identity} : Continuation<Nat, F.Owned>}
  finish(chunk(F.Owned, 8n, resume(Nat, F.Owned, all, Value{0n})))

type Results is Data:
  Results{composed: F.Summary, dependent: F.Summary, existential: F.Summary}

def main() -> Results:
  Results{composed(), dependent_site(), existential_type()}

