firstFailures.source:
import Base
import ./frames.bend as F

type Frame is Type:
  Bump{digit: Nat}
  Capture{owner: F.Owner, digit: Nat}
  Finish{digit: Nat}
  Keep{-A: Type, value: A}
  Select{site: F.Site, payload: F.Frame(site)}

def Input(frame: Frame) -> Type:
  match frame:
    case Bump{_}: Nat
    case Capture{_, _}: Nat
    case Finish{_}: F.Owned
    case Keep{_, _}: Nat
    case Select{site, _}: F.Input(site)

def Output(frame: Frame) -> Type:
  match frame:
    case Bump{_}: Nat
    case Capture{_, _}: F.Owned
    case Finish{_}: F.Owned
    case Keep{A, _}: A
    case Select{site, _}: F.Output(site)

type Continuation<-A: Type, -R: Type> is Type:
  Leaf{frame: Frame, input: {A == Input(frame) : Type}, output: {Output(frame) == R : Type}}
  Compose{-B: Type, first: Continuation<A, B>, next: Continuation<B, R>}
  Identity{equation: {A == R : Type}}

type Value<-A: Type> is Type:
  Value{value: A}

type Progress<-A: Type> is Type:
  Finished{box: Value<A>}
  Bound{-B: Type, inner: Progress<B>, resume: Continuation<B, A>}

def unbox(-A: Type, box: Value<A>) -> A:
  match box:
    case Value{value}: value

def apply(frame: Frame, box: Value<Input(frame)>) -> Progress<Output(frame)>:
  match frame:
    case Bump{digit}: Finished{Value{F.append(unbox(Nat, box), digit)}}
    case Capture{owner, digit}: Finished{Value{F.capture(owner, unbox(Nat, box), digit)}}
    case Finish{digit}:
      match box:
        case Value{F.Owned{owner, value, trace}}: Finished{Value{F.Owned{owner, value, F.append(trace, digit)}}}
    case Keep{A, value}: Finished{Value{value}}
    case Select{site, payload}: Finished{Value{F.apply(site, payload, unbox(F.Input(site), box))}}

def resume(-A: Type, -R: Type, continuation: Continuation<A, R>, box: Value<A>) -> Progress<R>:
  match continuation:
    case Leaf{frame, input, output}:
      %input : _
      %output : _
      apply(frame, box)
    case Compose{B, first, next}: Bound{B, resume(A, B, first, box), next}
    case Identity{equation}:
      %equation : _
      Finished{box}

def chunk(-A: Type, fuel: Nat, progress: Progress<A>) -> Progress<A>:
  match fuel progress:
    case 0n state: state
    case 1n+rest Finished{box}: Finished{box}
    case 1n+rest Bound{B, inner, continuation}:
      match inner:
        case Finished{box}: chunk(A, rest, resume(B, A, continuation, box))
        case Bound{C, nested, next}: chunk(A, rest, Bound{C, nested, Compose{B, next, continuation}})

def finish(progress: Progress<F.Owned>) -> F.Summary:
  match progress:
    case Finished{Value{value}}: F.close(value)
    case _: F.Summary{0n, 0n, 0n}

def composed() -> F.Summary:
  bump = {Leaf{Bump{3n}, {==}, {==}} : Continuation<Nat, Nat>}
  capture = {Leaf{Capture{F.Lease{7n}, 4n}, {==}, {==}} : Continuation<Nat, F.Owned>}
  finish_frame = {Leaf{Finish{5n}, {==}, {==}} : Continuation<F.Owned, F.Owned>}
  all = {Compose{Nat, bump, Compose{F.Owned, capture, finish_frame}} : Continuation<Nat, F.Owned>}
  finish(chunk(F.Owned, 16n, resume(Nat, F.Owned, all, Value{2n})))

def dependent_site() -> F.Summary:
  continuation = {Leaf{Select{F.CaptureSite{}, F.CaptureOwner{F.Lease{9n}, 8n}}, {==}, {==}} : Continuation<Nat, F.Owned>}
  finish(chunk(F.Owned, 8n, resume(Nat, F.Owned, continuation, Value{6n})))

def existential_type() -> F.Summary:
  continuation = {Leaf{Keep{F.Owned, F.Owned{F.Lease{11n}, 8n, 8n}}, {==}, {==}} : Continuation<Nat, F.Owned>}
  identity = {Identity{{==}} : Continuation<F.Owned, F.Owned>}
  all = {Compose{F.Owned, continuation, identity} : Continuation<Nat, F.Owned>}
  finish(chunk(F.Owned, 8n, resume(Nat, F.Owned, all, Value{0n})))

type Results is Data:
  Results{composed: F.Summary, dependent: F.Summary, existential: F.Summary}

def main() -> Results:
  Results{composed(), dependent_site(), existential_type()}
